fn='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    flat = sum(grid, [])
    background = max(set(flat), key=flat.count)
    colors = set(flat) - {background, 2}

    def line(r, c, dr, dc, paint, stop_color=None):
        while 0 <= r < h and 0 <= c < w:
            if stop_color is not None and grid[r][c] == stop_color:
                break
            if grid[r][c] == 2:
                out[r][c] = 4
            elif grid[r][c] == background:
                out[r][c] = paint
            r += dr
            c += dc

    # Edge color runs, when three or more cells long, mark alternating inward rows.
    for edge, dr in ((0, 1), (h - 1, -1)):
        runs = []
        c = 0
        while c < w:
            if grid[edge][c] in colors:
                col = grid[edge][c]
                end = c
                while end + 1 < w and grid[edge][end + 1] == col:
                    end += 1
                runs.append((c, end, col))
                c = end + 1
            else:
                c += 1
        for first, last, col in runs:
            if last - first + 1 >= 2:
                for step, cc in enumerate(range(first, last + 1)):
                    if step % 2 == 0:
                        line(edge + dr, cc, dr, 2 * dr, col, stop_color=col)

    # Uniform vertical edge bars project horizontally, filling through background
    # and converting embedded 2 markers to 4.
    for edge, dc in ((0, 1), (w - 1, -1)):
        rows = [r for r in range(h) if grid[r][edge] in colors]
        if len(rows) >= 2:
            col = grid[rows[0]][edge]
            if all(grid[r][edge] == col for r in rows) and rows == list(range(rows[0], rows[-1] + 1)):
                for r in rows:
