 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    flat = [v for row in grid for v in row]
    bg = max(set(flat), key=flat.count)

    # Find contiguous colored runs on the left and right borders. Matching
    # runs are paired panels; the one containing 2-markers is the source.
    def edge_runs(c):
        runs = []
        r = 0
        while r < h:
            color = grid[r][c]
            if color == bg or color in (0, 2):
                r += 1
                continue
            end = r
            while end + 1 < h and grid[end + 1][c] == color:
                end += 1
            runs.append((r, end, color))
            r = end + 1
        return runs

    left, right = edge_runs(0), edge_runs(w - 1)
    paired = False
    for la, lb, lc in left:
        for ra, rb, rc in right:
            if lc != rc or lb - la != rb - ra:
                continue
            left_has = any(2 in grid[r] for r in range(la, lb + 1))
            right_has = any(2 in grid[r] for r in range(ra, rb + 1))
            if left_has == right_has:
                continue
            paired = True
            if right_has:
                source, target, direction = (ra, rb), (la, lb), -1
            else:
                source, target, direction = (la, lb), (ra, rb), 1
            # Reproduce each source row's active pattern as a solid 2 band
            # in the corresponding row of its paired panel.
            for offset, sr in enumerate(range(source[0], source[1] + 1)):
                markers = [c for c, value in enumerate(grid[sr]) if value == 2]
                if not markers:
                    continue
                tr = target[0] + offset
                for c in range(w):
                    if grid[tr][c] == bg:
                        out[tr][c] = 2
                # Source markers turn to 4; extend their ray toward the source
                # panel's colored edge, painting intervening background 2.
                for mc in markers:
                    out[sr][mc] = 4
                    c = mc + direction
                    while 0 <= c < w and c not in (0, w - 1):
                        if grid[sr][c] == bg:
                            out[sr][c] = 2
                        elif grid[sr][c] == 2:
                            out[sr][c] = 4
                        else:
                            break
                        c += direction
            break
        if paired:
            break

    # If no matched colored edge panels exist, leave the input unchanged.
    return out


